def migrate_recipes_to_canonical(apps, schema_editor):
    """
    Data migration: Convert existing Recipe instances to CanonicalRecipe + user forks.

    Strategy:
    1. Group recipes by recipe_hash (unique dishes)
    2. For each unique hash, create ONE CanonicalRecipe
    3. Convert all Recipe instances with that hash to user forks
    """
    Recipe = apps.get_model('recipes', 'Recipe')
    CanonicalRecipe = apps.get_model('recipes', 'CanonicalRecipe')

    # Get all recipes
    all_recipes = Recipe.objects.all().select_related('created_by')

    if not all_recipes.exists():
        print("[MIGRATION] No recipes to migrate.")
        return

    # Group recipes by hash
    recipe_groups = {}
    for recipe in all_recipes:
        hash_key = recipe.recipe_hash
        if hash_key not in recipe_groups:
            recipe_groups[hash_key] = []
        recipe_groups[hash_key].append(recipe)

    print(f"[MIGRATION] Found {len(recipe_groups)} unique recipes (by hash)")

    # Create canonical recipes
    canonical_map = {}  # recipe_hash -> CanonicalRecipe

    for recipe_hash, recipe_list in recipe_groups.items():
        # Use the first recipe as the base for canonical
        base_recipe = recipe_list[0]

        # Create canonical recipe
        try:
            canonical = CanonicalRecipe.objects.create(
                name=base_recipe.name,
                description=base_recipe.description,
                source_type='ai_generated',  # All existing recipes came from AI
                ai_source_url=base_recipe.source_url,
                original_creator=base_recipe.created_by,
                base_ingredients=base_recipe.ingredients,
                base_steps=base_recipe.steps,
                cuisine=base_recipe.cuisine,
                difficulty=base_recipe.difficulty,
                diet_labels=base_recipe.diet_labels,
                prep_time_minutes=base_recipe.prep_time_minutes,
                cook_time_minutes=base_recipe.cook_time_minutes,
                total_time_minutes=base_recipe.total_time_minutes,
                servings=base_recipe.servings,
                recipe_hash=base_recipe.recipe_hash,
                created_at=base_recipe.created_at,
                updated_at=base_recipe.updated_at
            )
            canonical_map[recipe_hash] = canonical
            print(
                f"[MIGRATION] Created canonical: {canonical.name} (hash: {recipe_hash[:8]}...)")
        except Exception as e:
            print(
                f"[MIGRATION ERROR] Failed to create canonical for {base_recipe.name}: {e}")
            continue

    # Convert recipes to forks
    fork_count = 0
    for recipe in all_recipes:
        canonical = canonical_map.get(recipe.recipe_hash)
        if not canonical:
            continue

        # Convert to fork
        recipe.canonical_recipe = canonical
        recipe.is_fork = True
        recipe.user_modifications = {}  # Start with no modifications
        recipe.save(update_fields=['canonical_recipe',
                    'is_fork', 'user_modifications'])

        fork_count += 1

    # Update canonical statistics
    for canonical in canonical_map.values():
        fork_count_for_canonical = canonical.user_forks.count()
        total_cooked = sum(
            fork.times_cooked for fork in canonical.user_forks.all())

        canonical.total_saves = fork_count_for_canonical
        canonical.total_cooked = total_cooked
        canonical.save(update_fields=['total_saves', 'total_cooked'])

    print(f"[MIGRATION] Converted {fork_count} recipes to forks")
    print(f"[MIGRATION] Created {len(canonical_map)} canonical recipes")
    print("[MIGRATION] Migration complete!")


