    Recipe.objects.filter(is_fork=True).update(
        canonical_recipe=None,
        is_fork=False,
        user_modifications={}
    )

    # Delete all canonical recipes
    CanonicalRecipe.objects.all().delete()

    print("[MIGRATION] Reversed migration - deleted canonical recipes")


